/* user_grant.who : target  at AbsoluteStatic(0x05)
 * size=Bounded(1, 64) align=Aligned(1) repr=TextConverted atomic=NonAtomic mutate=Shifting
 */
/** How many bytes `who` occupies, measured at an
 * offset the caller already knows. Summing these forward is
 * what keeps an offset chain linear.
 */
static inline uint32_t fzn_permit_user_grant_who_extent_from(situ_view_t view, uint32_t base)
{
	situ_view_t whole;

	if (situ_view_sub(view, base, situ_remaining_u32(view.limit, base), &whole) != SITU_OK) {
		return 0u;
	}
	return fzn_permit_target_extent(whole);
}

/** How many bytes `who` occupies here. The
 * member after it starts at the end of this, and that was a
 * constant zero until `target` stopped having one size --
 * so the next member was placed on top of this one.
 */
static inline uint32_t fzn_permit_user_grant_who_extent(situ_view_t view)
{
	return fzn_permit_user_grant_who_extent_from(view, 5u);
}

/** `who` has no one size, so its extent is read
 * from the bytes. The sub-view is taken twice: once over what
 * is left, to give the extent function something to measure,
 * and once at the size it reports.
 */
static inline situ_err_t fzn_permit_user_grant_who_view(situ_view_t view, situ_view_t *out)
{
	const uint32_t base = 5u;
	situ_view_t whole;
	situ_err_t  e;

	e = situ_view_sub(view, base, situ_remaining_u32(view.limit, base), &whole);
	if (e != SITU_OK) {
		return e;
	}
	return situ_view_sub(view, base, fzn_permit_target_extent(whole), out);
}

